import React, { useState, useRef } from 'react';

const DocumentUpload = ({ onSendDocument }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      // Basic validation (can be expanded)
      const allowedTypes = ['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document']; // PDF and DOCX
      if (allowedTypes.includes(file.type)) {
        setSelectedFile(file);
        console.log('File selected:', file.name);
      } else {
        alert('Invalid file type. Please upload PDF or DOCX only.');
        setSelectedFile(null);
        if(fileInputRef.current) fileInputRef.current.value = null; // Reset file input
      }
    }
  };

  const handleUpload = () => {
    if (selectedFile) {
      setIsUploading(true);
      // Simulate upload and then call onSendDocument
      console.log(`Simulating upload of ${selectedFile.name}...`);
      setTimeout(() => {
        if (onSendDocument) {
          onSendDocument({ type: 'document', content: selectedFile, name: selectedFile.name });
        } else {
          alert(`Document "${selectedFile.name}" ready for processing (simulated).`);
        }
        setSelectedFile(null);
        setIsUploading(false);
        if(fileInputRef.current) fileInputRef.current.value = null; // Reset file input
      }, 1500); // Simulate network delay
    } else {
      alert('Please select a file to upload.');
    }
  };

  const containerStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '10px'
  };

  const inputStyle = {
    // display: 'none' // Can hide and style a label instead for better UX
    fontSize: '14px',
    maxWidth: '200px' // Prevent input from becoming too wide
  };

  const buttonStyle = {
    padding: '8px 12px',
    border: 'none',
    backgroundColor: 'var(--secondary-color)',
    color: 'white',
    borderRadius: 'var(--border-radius, 8px)',
    cursor: 'pointer',
    fontSize: '14px',
  };

  return (
    <div style={containerStyle}>
      <input 
        type="file" 
        ref={fileInputRef}
        onChange={handleFileChange} 
        accept=".pdf,.docx" 
        style={inputStyle}
        disabled={isUploading}
      />
      <button onClick={handleUpload} disabled={!selectedFile || isUploading} style={buttonStyle}>
        {isUploading ? 'Uploading...' : 'Upload Doc'}
      </button>
    </div>
  );
};

export default DocumentUpload;
